function [thetabanane,thetaloss,pndetrap,Eseuil,delta] = detrapmj3(zeff,a,B0,R0,BeLi,Ip,ne,rho)% calculations of losscone angle and detrapping momentum  %rho; Normalized magnetic surface (r/a) %a; Plasma minor radius (m)%R0; Major radius (m)%zeff%Ip; Plsama current (MA)%BeLi = 'beta + Li/2' %delta; Magnetic ripple depth%Eseuil; Threshold energy (keV)%thetabanane; Banana angle w.r.t. pperp direction (deg)%thetaloss; Magnetic ripple loss cone angle w.r.t. pperp direction (deg)%pndetrap; Normalized magnetic ripple detrapping momentum %ne; (/m3)%D0; Shaf. shift (m) D0    =  a^2*(BeLi-0.5)/(2*R0);   %magnetic ripple depth   delta = deltacalmj3(R0 + a*rho,zeros(size(rho)));%% Calculation of loss cone angle 'thetaloss'     thetaconemj3;% Calculation of threshold energy and normalised detrapping momentum 'pndetrap'E      = [0:1:350];le     = length(E);for k2=1:le;    F(k2) = fracmircalcmj3(E(k2),delta,ne,zeff,a,R0,B0,NBOB);end indF      = find(F<=1);Eseuil = sum(E(indF).*(1-F(indF)))/sum(1-F(indF));     if thetaZBC~=0   Es    = Eseuil;   pndetrap  = sqrt((Es/511+1).^2-1);end